-- =====================================================================
-- Taraj Global Solutions - HRMS Initial Seed Data
-- =====================================================================

USE `hrims`;

-- 1. Seed 8 Core Standard Departments
ON DUPLICATE KEY UPDATE `name`=VALUES(`name`), `description`=VALUES(`description`);

-- 2. Seed Standard Positions for each Department
-- Quality
(1, 1, 'QA_ENG', 'QA Automation Engineer', 'Develop test automation suites and verify software quality.', 'Selenium, Playwright, Cypress, CI/CD knowledge.', 1),
(2, 1, 'QA_MAN', 'Manual Test Specialist', 'Functional, regression, and cross-browser testing specialist.', 'Strong test case design, Jira, Bugzilla experience.', 1),
-- Development
(3, 2, 'DEV_FULLSTACK', 'Full Stack Developer', 'Design and implement Next.js, Node.js and SQL applications.', 'Next.js, React, Node.js, MySQL, TypeScript.', 1),
(4, 2, 'DEV_BACKEND', 'Backend Engineer', 'Develop scalable APIs, database queries and microservices.', 'Node.js, Express, MySQL, Redis, REST APIs.', 1),
(5, 2, 'DEV_FRONTEND', 'Frontend Engineer', 'Build modern, accessible, responsive web interfaces.', 'React, TypeScript, Tailwind CSS, Performance optimization.', 1),
-- Management
(6, 3, 'PM_TECH', 'Technical Project Manager', 'Coordinate sprints, roadmap planning and technical delivery.', 'Scrum/Agile certification, Jira, resource planning.', 1),
(7, 3, 'PROD_MGR', 'Product Manager', 'Define product vision, user stories, and feature prioritization.', 'Product roadmapping, UX metrics, stakeholder mgmt.', 1),
-- Sales & Demand Generation
(8, 4, 'SALES_BDE', 'Business Development Executive', 'B2B lead generation, prospect calling and client engagement.', 'Excellent verbal communication, CRM expertise.', 1),
(9, 4, 'SALES_MGR', 'Enterprise Sales Manager', 'Close enterprise contracts and oversee sales pipelines.', 'B2B tech sales track record, contract negotiation.', 1),
(18, 4, 'DEMAND_GEN', 'Demand Generation Specialist', 'Drive B2B demand generation, inbound/outbound pipeline and ABM campaigns.', 'ICP definition, MQL/SQL lifecycle, BANT, ABM, Campaign tracking.', 1),
-- HR
(10, 5, 'HR_RECRUITER', 'Technical Recruiter', 'Sourcing, screening, and coordinating recruitment rounds.', 'Tech talent sourcing, ATS management, behavioral interviewing.', 1),
(11, 5, 'HR_EXEC', 'HR Operations Executive', 'Employee onboarding, documentation, and compliance support.', 'Labor law knowledge, HRMS operations, onboarding.', 1),
-- Operations
(12, 6, 'OPS_SYSADMIN', 'System Administrator', 'Manage on-premise hardware, networks, and workstation security.', 'Linux, Windows Server, Networking, Active Directory.', 1),
(13, 6, 'OPS_COORD', 'Operations Coordinator', 'Facilities management and operational vendor coordination.', 'Vendor management, facilities oversight, procurement.', 1),
-- DBMS
(14, 7, 'DBA_MYSQL', 'MySQL Database Administrator', 'Maintain high availability, query optimization, and backups.', 'MySQL 8+, indexing, replication, performance tuning.', 1),
(15, 7, 'DATA_ENG', 'Data Engineer', 'Build ETL pipelines and maintain data warehouses.', 'SQL, Python, ETL tools, schema normalization.', 1),
-- Email Marketing
(16, 8, 'EMAIL_SPEC', 'Email Marketing Specialist', 'Execute email campaigns, A/B testing and monitor deliverability.', 'Klaviyo, Mailchimp, HTML email templating, SPF/DKIM.', 1),
(17, 8, 'EMAIL_STRAT', 'Lifecycle Campaign Strategist', 'Customer journeys, automated drip sequences, and retention metrics.', 'Audience segmentation, copywriting, analytical reporting.', 1)
ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`);

-- 3. Seed Default System Users (Assigned Managers across all 8 Departments - Default password: admin123)
ON DUPLICATE KEY UPDATE `email`=VALUES(`email`), `password_hash`=VALUES(`password_hash`), `full_name`=VALUES(`full_name`);

-- 4. Question Categories
ON DUPLICATE KEY UPDATE `name`=VALUES(`name`), `description`=VALUES(`description`);

-- 5. Standardized Interview Questions across all 3 Rounds
-- Round 1: Common HR Screening (Official 10 Questions: Section A - 5 HR Questions, Section B - 5 Scenario Questions)
ON DUPLICATE KEY UPDATE `question_text`=VALUES(`question_text`), `expected_answer_guidance`=VALUES(`expected_answer_guidance`), `question_type`=VALUES(`question_type`), `category_id`=VALUES(`category_id`), `department_id`=VALUES(`department_id`), `round_type`=VALUES(`round_type`), `is_active`=1;
