(2, 'hrmanager@2207.com', 'hrmanager@2207.com', '6bd0a1a055fecbeab84264f952c0cff9:d4a219e9088a81fd9700113f58d8efeb070c3f44d40f661d43980c5fbdd885ad1ba66ce13edfdc453309a373f1eb428b9690d41776f6d8a4eec4a4e8609a8db5', 'Pooja Kumari (HR Manager)', 'hr_manager', 5, 1),
(3, 'devlead', 'dev.lead@tarajglobalsolutions.com', '9137edf3239fb0a881e29d3c7671b989:5608a61554b0dd31588145592c65041c8c91e8419dd1036d2ec418054fd622c0ee30e437333257e2be13a947d8772e4ba8294d2962518a64f16b246be6fd9941', 'Michael Chen (Dev Lead)', 'dept_manager', 2, 1),
(4, 'qalead', 'qa.lead@tarajglobalsolutions.com', '9137edf3239fb0a881e29d3c7671b989:5608a61554b0dd31588145592c65041c8c91e8419dd1036d2ec418054fd622c0ee30e437333257e2be13a947d8772e4ba8294d2962518a64f16b246be6fd9941', 'Emily Davis (QA Lead)', 'dept_manager', 1, 1),
(5, 'dbasuper', 'dba.lead@tarajglobalsolutions.com', '9137edf3239fb0a881e29d3c7671b989:5608a61554b0dd31588145592c65041c8c91e8419dd1036d2ec418054fd622c0ee30e437333257e2be13a947d8772e4ba8294d2962518a64f16b246be6fd9941', 'David Vance (DBMS Lead)', 'dept_manager', 7, 1),
(6, 'mgmtlead', 'mgmt.lead@tarajglobalsolutions.com', '9137edf3239fb0a881e29d3c7671b989:5608a61554b0dd31588145592c65041c8c91e8419dd1036d2ec418054fd622c0ee30e437333257e2be13a947d8772e4ba8294d2962518a64f16b246be6fd9941', 'Robert Taylor (Management Lead)', 'dept_manager', 3, 1),
(7, 'saleslead', 'sales.lead@tarajglobalsolutions.com', '9137edf3239fb0a881e29d3c7671b989:5608a61554b0dd31588145592c65041c8c91e8419dd1036d2ec418054fd622c0ee30e437333257e2be13a947d8772e4ba8294d2962518a64f16b246be6fd9941', 'Alexander Wright (Sales & Demand Gen Director)', 'dept_manager', 4, 1),
(8, 'opslead', 'ops.lead@tarajglobalsolutions.com', '9137edf3239fb0a881e29d3c7671b989:5608a61554b0dd31588145592c65041c8c91e8419dd1036d2ec418054fd622c0ee30e437333257e2be13a947d8772e4ba8294d2962518a64f16b246be6fd9941', 'Frank Martinez (Operations Lead)', 'dept_manager', 6, 1),
(9, 'emaillead', 'email.lead@tarajglobalsolutions.com', '9137edf3239fb0a881e29d3c7671b989:5608a61554b0dd31588145592c65041c8c91e8419dd1036d2ec418054fd622c0ee30e437333257e2be13a947d8772e4ba8294d2962518a64f16b246be6fd9941', 'Lisa Wong (Email Marketing Lead)', 'dept_manager', 8, 1)
INSERT INTO `question_categories` (`id`, `name`, `description`) VALUES
(1, 'Communication & Soft Skills', 'Clarity of thought, articulation, confidence and interpersonal etiquette'),
(2, 'Technical Core & Problem Solving', 'Domain-specific knowledge, architecture understanding, and troubleshooting'),
(3, 'Culture & Company Values', 'Team collaboration, alignment with Taraj Global values, and work ethic'),
(4, 'Leadership & Situational', 'Conflict resolution, ownership, and adaptability under pressure'),
(5, 'Practical Task & Problem Solving', 'Hands-on task resolution, scenario debugging, and domain problem solving')
INSERT INTO `interview_questions` (`id`, `department_id`, `position_id`, `round_type`, `category_id`, `question_text`, `question_type`, `expected_answer_guidance`, `max_score`, `time_limit_seconds`, `weight`, `is_active`) VALUES
(201, NULL, NULL, 'hr', 1, 'Tell me about yourself and explain the skills or experiences that make you suitable for this role.', 'hr', 'Section A: HR Question. Evaluate communication clarity, relevant educational/professional background, personal strengths, and suitability for the role.', 10, 180, 1.00, 1),
(202, NULL, NULL, 'hr', 1, 'Why do you want to join our company, and what do you know about our B2B business?', 'hr', 'Section A: HR Question. Evaluate company research, understanding of B2B business model, motivation to work at Taraj Global Solutions, and organizational fit.', 10, 180, 1.00, 1),
(203, NULL, NULL, 'hr', 1, 'What are your strengths and weaknesses, and how are you working to improve yourself?', 'hr', 'Section A: HR Question. Evaluate self-awareness, authentic strengths with real examples, self-critique maturity, and active personal development steps.', 10, 180, 1.00, 1),
(204, NULL, NULL, 'hr', 1, 'How do you handle constructive feedback from your manager or senior team members?', 'hr', 'Section A: HR Question. Evaluate emotional maturity, coachability, positive attitude towards feedback, and willingness to adapt and improve.', 10, 180, 1.00, 1),
(205, NULL, NULL, 'hr', 1, 'Why should we hire you for this position, and what value can you contribute to our team?', 'hr', 'Section A: HR Question. Evaluate candidate value proposition, enthusiasm, understanding of deliverables, and team commitment.', 10, 180, 1.00, 1),
(206, NULL, NULL, 'hr', 1, 'You have an important task due today, but an unexpected problem may prevent you from completing it on time. What would you do?', 'scenario', 'Section B: Scenario-Based Question. Evaluate: (1) Problem identification & impact assessment, (2) Prompt and transparent communication with manager, (3) Proactive proposed mitigation or revised delivery schedule.', 10, 240, 1.00, 1),
(207, NULL, NULL, 'hr', 1, 'You and your teammate disagree about how to complete a task. Both of you believe your approach is correct. How would you resolve the situation?', 'scenario', 'Section B: Scenario-Based Question. Evaluate: (1) Active, respectful listening, (2) Objective comparison using facts and company goals, (3) Compromise or involving a lead/manager constructively.', 10, 240, 1.00, 1),
(208, NULL, NULL, 'hr', 1, 'Your manager assigns you three tasks, and all have urgent deadlines. How would you prioritize and complete them?', 'scenario', 'Section B: Scenario-Based Question. Evaluate: (1) Urgency vs impact matrix, (2) Seeking manager alignment on priorities, (3) Time-boxing, execution focus, and proactive progress updates.', 10, 240, 1.00, 1),
(209, NULL, NULL, 'hr', 1, 'You discover that you submitted incorrect information that could affect your team or a client. What steps would you take?', 'scenario', 'Section B: Scenario-Based Question. Evaluate: (1) Honesty and immediate disclosure, (2) Accountability without blame-shifting, (3) Rectifying the data/impact, and (4) Establishing safeguards against recurrence.', 10, 240, 1.00, 1),
(210, NULL, NULL, 'hr', 1, 'Your manager assigns you a task you have never done before and is temporarily unavailable. How would you approach it?', 'scenario', 'Section B: Scenario-Based Question. Evaluate: (1) Independent research and reviewing documentation, (2) Consulting knowledgeable peers or guidelines, (3) Preparing draft/framework, and (4) Validating with manager upon return.', 10, 240, 1.00, 1),
(8, 1, NULL, 'department', 2, 'What is the difference between Manual Testing and Automated Testing, and when should you use each?', 'technical', 'Manual for exploratory, ad-hoc and UI usability testing; Automated for repetitive regression and continuous integration suites.', 10, 180, 1.25, 1),
(9, 1, NULL, 'department', 2, 'Can you explain what a Test Case is and what key information every good test case should contain?', 'technical', 'Test Case ID, Title, Preconditions, Step-by-step instructions, Test Data, Expected Result, and Actual Result.', 10, 180, 1.25, 1),
(31, 1, NULL, 'department', 2, 'When you discover a bug in an application, what steps do you take to verify and report it clearly to the developers?', 'technical', 'Reproduce bug reliably, isolate variables, capture logs/screenshots, write clear steps to reproduce in bug tracker.', 10, 180, 1.25, 1),
(5, 2, NULL, 'department', 2, 'Can you explain the difference between frontend and backend in a modern web application?', 'technical', 'Frontend handles user interface, design, and user interactions; Backend handles database, APIs, authentication, and server logic.', 10, 180, 1.25, 1),
(6, 2, NULL, 'department', 2, 'What are RESTful APIs, and what is the difference between a GET and a POST request?', 'technical', 'REST APIs communicate over HTTP methods; GET fetches data without modifying state; POST sends payload to create or process data.', 10, 180, 1.25, 1),
(7, 2, NULL, 'department', 2, 'How do you use Git version control in your day-to-day work for creating branches, committing changes, and pushing code?', 'technical', 'git checkout -b branch-name, git add, git commit with meaningful message, git push, and pull request review.', 10, 180, 1.25, 1),
(32, 2, NULL, 'department', 2, 'How do you approach debugging when a web page throws an unexpected error in the browser or terminal console?', 'technical', 'Inspect console stack trace, check network tab requests/responses, review recent code diffs, verify state variables.', 10, 180, 1.25, 1),
(25, 3, NULL, 'department', 4, 'What is the difference between Agile and traditional Waterfall project management methodologies?', 'situational', 'Agile uses flexible, short sprints and continuous collaboration; Waterfall follows linear, rigid phases from requirements to delivery.', 10, 180, 1.25, 1),
(26, 3, NULL, 'department', 4, 'How do you track daily project progress and ensure team members meet their sprint deliverables without feeling micromanaged?', 'situational', 'Short daily standups, clear Kanban/Scrum board updates, transparent sprint goals, removing roadblocks quickly.', 10, 180, 1.25, 1),
(33, 3, NULL, 'department', 4, 'How do you communicate with clients or stakeholders when a feature delivery might take longer than originally planned?', 'situational', 'Proactive early communication, explaining root cause honestly, presenting realistic revised dates and solutions.', 10, 180, 1.25, 1),
(15, 4, NULL, 'department', 2, 'What is the difference between Inbound leads and Outbound leads in sales?', 'technical', 'Inbound leads discover the company through content/website and reach out; Outbound leads are contacted directly via cold outreach.', 10, 180, 1.25, 1),
(16, 4, NULL, 'department', 2, 'How do you research a prospective company or client before picking up the phone or sending a cold outreach message?', 'technical', 'Review LinkedIn profile, company website, recent news, industry challenges, identifying key decision-maker titles.', 10, 180, 1.25, 1),
(17, 4, NULL, 'department', 2, 'When a prospect says "We are not interested right now", how do you politely respond to understand their reasoning and keep the door open?', 'situational', 'Acknowledge gracefully, ask polite question about current workflow or timeline, ask permission to share a case study for future.', 10, 180, 1.25, 1),
(20, 4, NULL, 'department', 2, 'What essential information do you record in a CRM (like HubSpot or Salesforce) to ensure smooth sales follow-ups?', 'technical', 'Prospect name, company, pain points discussed, agreed next action, follow-up date, deal stage, and decision-maker roles.', 10, 180, 1.25, 1),
(29, 5, NULL, 'department', 1, 'What key steps do you follow when sourcing and screening resumes for an open job requirement?', 'technical', 'Analyze job description criteria, review relevant work experience, check technical/soft skills fit, evaluate resume clarity.', 10, 180, 1.25, 1),
(30, 5, NULL, 'department', 4, 'How do you coordinate with department managers to understand what skills they are looking for in a new hire?', 'situational', 'Conduct recruitment intake meeting, align on required vs preferred skills, set realistic salary/experience benchmarks.', 10, 180, 1.25, 1),
(34, 5, NULL, 'department', 3, 'What makes a welcoming first-day onboarding experience for a new employee joining the company?', 'situational', 'Prepared workstation, designated onboarding buddy, clear first-day agenda, warm team introduction, and HR orientation.', 10, 180, 1.25, 1),
(27, 6, NULL, 'department', 2, 'What are the common daily responsibilities of an operations team in an IT company?', 'technical', 'Facilities management, workstation and IT asset management, vendor coordination, procurement, process adherence.', 10, 180, 1.25, 1),
(28, 6, NULL, 'department', 4, 'If an office network or workstation suddenly stops connecting to the internet, what basic troubleshooting steps do you take?', 'situational', 'Check ethernet cables/Wi-Fi switch, ping default gateway, check DNS settings, restart network adapter or router.', 10, 180, 1.25, 1),
(35, 6, NULL, 'department', 2, 'How do you keep track of office IT assets (laptops, monitors, credentials) and vendor supplies?', 'technical', 'Asset inventory tracking sheet, serial numbers, allocation logs, checkout agreements, scheduled physical audits.', 10, 180, 1.25, 1),
(10, 7, NULL, 'department', 2, 'What is a Primary Key and a Foreign Key in a relational database like MySQL, and why are they important?', 'technical', 'Primary key uniquely identifies each table record; Foreign key establishes relationship between tables and prevents orphan rows.', 10, 180, 1.25, 1),
(24, 7, NULL, 'department', 2, 'What is the difference between WHERE and HAVING clauses in an SQL query?', 'technical', 'WHERE filters rows before grouping; HAVING filters summary rows after GROUP BY aggregation.', 10, 180, 1.25, 1),
(36, 7, NULL, 'department', 2, 'Why are regular database backups essential, and what is the difference between full and incremental backups?', 'technical', 'Disaster recovery and business continuity; Full backup copies all data; Incremental copies only data modified since last backup.', 10, 180, 1.25, 1),
(21, 8, NULL, 'department', 2, 'What are the key metrics used to measure the success of an email marketing campaign (Open Rate, Click Rate, Unsubscribe Rate)?', 'technical', 'Open rate reflects subject line interest; Click rate reflects engagement and offer appeal; Unsubscribe/bounce shows list health.', 10, 180, 1.25, 1),
(22, 8, NULL, 'department', 2, 'What best practices do you follow to ensure marketing emails don''t end up in the spam folder?', 'technical', 'Verify SPF, DKIM, DMARC records, maintain clean opted-in email lists, avoid spam trigger words, include clear unsubscribe link.', 10, 180, 1.25, 1),
(23, 8, NULL, 'department', 2, 'How do you segment an email subscriber list to send more relevant messages to different audiences?', 'technical', 'Segment by engagement level, buyer personas, industry, previous purchase/download behavior to improve relevance.', 10, 180, 1.25, 1),
(41, 1, NULL, 'final', 5, 'Practical Task 1: Write 3 simple test cases for a candidate registration form (Fields: Full Name, Email, Phone Number). Include 1 positive case and 2 negative validation cases.', 'practical', 'Positive case with all valid values; Negative 1 with invalid email syntax; Negative 2 with empty phone or required field missing.', 10, 240, 1.50, 1),
(42, 1, NULL, 'final', 5, 'Practical Task 2: A candidate clicks "Submit Application" but nothing happens and no message appears. Write a clear bug report with Title, Steps to Reproduce, Expected Result, and Actual Result.', 'practical', 'Clear title, numbered steps to reproduce, expected submission success or error message, actual silent failure.', 10, 240, 1.50, 1),
(43, 1, NULL, 'final', 5, 'Practical Task 3: Test an age input field where the allowed age is between 18 and 60. List the specific boundary values you will test to verify validation rules.', 'practical', 'Boundary values: 17 (just below min - invalid), 18 (min - valid), 19 (valid), 59 (valid), 60 (max - valid), 61 (just above max - invalid).', 10, 240, 1.50, 1),
(44, 1, NULL, 'final', 5, 'Practical Task 4: Review a simple user login screen with a "Remember Me" checkbox. List 4 quick functional checks you would perform before approving the build for release.', 'practical', '1. Valid login credentials, 2. Invalid password error, 3. Blank fields validation, 4. Remember Me cookie/session persistence on browser restart.', 10, 240, 1.50, 1),
(45, 1, NULL, 'final', 5, 'Practical Task 5: A developer fixed a reported bug in the candidate search filter. Explain what regression testing checks you will perform to confirm no other feature was broken.', 'practical', 'Verify the bug fix itself, test other department filters, test pagination, check search reset button, check mobile responsiveness.', 10, 240, 1.50, 1),
(11, 2, NULL, 'final', 5, 'Practical Task 1: Write a simple SQL query to retrieve the full name and email of all candidates who applied for the "Development" department and have status "new".', 'practical', 'SELECT full_name, email FROM candidates WHERE department_id = 2 AND status = ''new'';', 10, 240, 1.50, 1),
(12, 2, NULL, 'final', 5, 'Practical Task 2: Write a short JavaScript function isValidEmail(email) that returns true if the email string contains "@" and ".", and false otherwise.', 'practical', 'function isValidEmail(email) { return email && email.includes("@") && email.includes("."); }', 10, 240, 1.50, 1),
(13, 2, NULL, 'final', 5, 'Practical Task 3: In a React component, explain how you would show a "Loading..." indicator while fetching candidate data from an API, and display the candidate list once loaded.', 'practical', 'Define useState for loading (true/false) and candidates (array); fetch in useEffect on mount; conditionally render spinner or candidates list.', 10, 240, 1.50, 1),
(37, 2, NULL, 'final', 5, 'Practical Task 4: An API endpoint returns HTTP 500 error when submitting an interview score. What are the 3 immediate steps you take to trace and fix the issue?', 'practical', '1. Check terminal/server console for crash error stack, 2. Inspect request payload in network tab, 3. Validate SQL parameters and database columns.', 10, 240, 1.50, 1),
(38, 2, NULL, 'final', 5, 'Practical Task 5: Write the Git commands to create a new branch called "feature/candidate-notes", commit your changes with a message, and push it to GitHub.', 'practical', 'git checkout -b feature/candidate-notes; git add .; git commit -m "Add candidate notes feature"; git push -u origin feature/candidate-notes;', 10, 240, 1.50, 1),
(51, 3, NULL, 'final', 5, 'Practical Task 1: You need to deliver a new "QR Code Onboarding" feature in a 2-week sprint. Break down this feature into 3 clear, manageable user stories or tasks.', 'practical', '1. Generate and display QR code on portal, 2. Mobile registration form for candidates, 3. Secure backend submission and database entry.', 10, 240, 1.50, 1),
(52, 3, NULL, 'final', 5, 'Practical Task 2: A developer informs you on Thursday afternoon that a key deliverable promised for Friday will be delayed by 2 days. Draft a short, professional update note to the stakeholder.', 'practical', 'Polite tone, transparent reason for delay, realistic revised date (Monday), highlighting thorough testing to preserve quality.', 10, 240, 1.50, 1),
(53, 3, NULL, 'final', 5, 'Practical Task 3: You have 3 urgent items: (A) A typo on the website homepage, (B) A bug preventing candidates from submitting applications, (C) Sprint planning for next month. Order them 1 to 3 by priority and briefly explain why.', 'practical', 'Priority 1: B (business blocking), Priority 2: A (quick public-facing fix), Priority 3: C (strategic planning done after unblocking users).', 10, 240, 1.50, 1),
(54, 3, NULL, 'final', 5, 'Practical Task 4: Design a clean 15-minute daily standup agenda for a team of 6 engineers to keep everyone aligned without running over time.', 'practical', 'Round-robin format: What did I complete yesterday? What am I working on today? Any blockers? Strict 2 minutes per person with parking lot for deeper discussions.', 10, 240, 1.50, 1),
(55, 3, NULL, 'final', 5, 'Practical Task 5: The sprint just concluded. Write 2 specific questions you would ask the team in a retrospective meeting to help improve the next sprint.', 'practical', '1. What went exceptionally well that we should repeat? 2. What slowed us down or could be streamlined in our workflow?', 10, 240, 1.50, 1),
(61, 4, NULL, 'final', 5, 'Practical Task 1: Draft a short, professional 3-sentence introductory email to an HR Director offering a 15-minute demonstration of Taraj Global Solutions'' recruitment software.', 'practical', 'Sentence 1: Personalized hook on automating hiring workflows. Sentence 2: Core value of 3-round assessments and QR onboarding. Sentence 3: Low-friction call to action for a 15-minute demo.', 10, 240, 1.50, 1),
(62, 4, NULL, 'final', 5, 'Practical Task 2: During a discovery call, a prospect says: "We currently manage all recruitment in Excel sheets and it works fine for us." Write a polite response highlighting the benefits of upgrading.', 'practical', 'Acknowledge spreadsheet ease, point out risks of lost candidate records, emphasize automated QR code registration, scorecards, and time savings.', 10, 240, 1.50, 1),
(63, 4, NULL, 'final', 5, 'Practical Task 3: If you make 50 cold calls per day, 10 prospects agree to receive company details, and 2 book a qualified product demo, calculate your conversion rate from calls to booked demos.', 'practical', '(2 booked demos / 50 total calls) * 100 = 4.0% conversion rate.', 10, 240, 1.50, 1),
(64, 4, NULL, 'final', 5, 'Practical Task 4: A prospect agreed to a demo but has not accepted the calendar invite after 48 hours. Write a friendly, 2-sentence follow-up message.', 'practical', 'Friendly reminder with meeting time, offering flexibility to reschedule if original time no longer works.', 10, 240, 1.50, 1),
(65, 4, NULL, 'final', 5, 'Practical Task 5: List the 4 key qualifying details (BANT or checklist) you must collect from a lead before passing them over to an Account Executive.', 'practical', 'Budget indication, Authority/Decision maker identity, business Need/pain point, and expected Timeline for rollout.', 10, 240, 1.50, 1),
(71, 5, NULL, 'final', 5, 'Practical Task 1: Draft a friendly and professional email invitation to a candidate who passed Round 1, confirming the date, time, and link for Round 2: Department Interview.', 'practical', 'Warm congratulatory opening, interview date & time, interviewer title, interview link/location, invitation to ask any questions.', 10, 240, 1.50, 1),
(72, 5, NULL, 'final', 5, 'Practical Task 2: A selected candidate is offered $50,000/year but requests $55,000. How do you handle this response professionally while consulting internal leadership?', 'practical', 'Express gratitude for transparency, validate their interest, state you will review budget with hiring managers, set clear timeline for response.', 10, 240, 1.50, 1),
(73, 5, NULL, 'final', 5, 'Practical Task 3: Create a simple 5-step checklist for a new employee''s Day 1 to ensure they feel welcomed and properly onboarded.', 'practical', '1. Welcome desk & badge, 2. IT login/laptop handoff, 3. Team introduction & buddy lunch, 4. HR policies overview, 5. Manager 1-on-1 expectations sync.', 10, 240, 1.50, 1),
(74, 5, NULL, 'final', 5, 'Practical Task 4: Two candidates have identical interview scores: Candidate A has stronger communication skills, while Candidate B has 1 extra year of experience. What factors would you consider to make a recommendation?', 'practical', 'Examine team balance, communication requirement of the role, cultural adaptability, long-term learning agility.', 10, 240, 1.50, 1),
(75, 5, NULL, 'final', 5, 'Practical Task 5: An interviewer has not submitted their evaluation remarks 24 hours after an interview ended. Draft a polite, professional reminder note.', 'practical', 'Polite greeting, mention candidate name and round, stress timely feedback for candidate experience, provide direct link to scorecard.', 10, 240, 1.50, 1),
(81, 6, NULL, 'final', 5, 'Practical Task 1: Create an IT onboarding checklist of 5 physical and digital items that must be prepared before a new employee arrives on their first day.', 'practical', '1. Configured laptop/OS, 2. Corporate email & chat credentials, 3. Office security access card, 4. Peripheral hardware (mouse/headset), 5. Wi-Fi connection profile.', 10, 240, 1.50, 1),
(82, 6, NULL, 'final', 5, 'Practical Task 2: An employee reports that their office laptop cannot connect to the Wi-Fi network, but other devices connect fine. List 3 basic troubleshooting steps to guide them through.', 'practical', '1. Turn Wi-Fi switch off and on, 2. Forget network and re-type password, 3. Restart device network adapter or run Windows network troubleshooter.', 10, 240, 1.50, 1),
(83, 6, NULL, 'final', 5, 'Practical Task 3: The office main internet connection goes down during working hours. Write a concise, reassuring message to notify staff and state when the next update will occur.', 'practical', 'Clear statement of ISP outage, fallback procedure (mobile hotspot/local work), reassurance that ISP ticket is open, update promised within 30 minutes.', 10, 240, 1.50, 1),
(84, 6, NULL, 'final', 5, 'Practical Task 4: Outline a simple weekly checklist to verify that automated database backups are completing successfully and not running out of disk space.', 'practical', '1. Check backup timestamp log, 2. Verify non-zero file size, 3. Check disk storage capacity, 4. Confirm backup retention pruning ran correctly.', 10, 240, 1.50, 1),
(85, 6, NULL, 'final', 5, 'Practical Task 5: You need to purchase 5 new keyboards and mice for the office. What 3 steps do you take to compare vendor quotes and obtain purchase approval?', 'practical', '1. Request quotes from 2-3 approved suppliers, 2. Compare price, warranty, delivery speed, 3. Submit PO summary for manager sign-off.', 10, 240, 1.50, 1),
(91, 7, NULL, 'final', 5, 'Practical Task 1: Write an SQL query to find the total number of candidates in each department, displaying the department name and total candidate count.', 'practical', 'SELECT d.name, COUNT(c.id) AS total_candidates FROM departments d LEFT JOIN candidates c ON d.id = c.department_id GROUP BY d.name;', 10, 240, 1.50, 1),
(92, 7, NULL, 'final', 5, 'Practical Task 2: Candidate with ID 105 has an updated phone number "9876543210" and status "interview_scheduled". Write the SQL UPDATE statement to save these changes.', 'practical', 'UPDATE candidates SET phone = ''9876543210'', status = ''interview_scheduled'' WHERE id = 105;', 10, 240, 1.50, 1),
(93, 7, NULL, 'final', 5, 'Practical Task 3: A query "SELECT * FROM candidates WHERE email = ?" is running slowly on a table with 100,000 rows. What SQL command do you write to add an index on the email column?', 'practical', 'CREATE INDEX idx_candidates_email ON candidates(email); or ALTER TABLE candidates ADD INDEX (email);', 10, 240, 1.50, 1),
(94, 7, NULL, 'final', 5, 'Practical Task 4: Explain the difference between "DELETE FROM candidates WHERE id = 5;" and "TRUNCATE TABLE candidates;" in terms of data safety and ability to rollback.', 'practical', 'DELETE removes specific rows, can be rolled back in a transaction, maintains autoincrement counter; TRUNCATE empties whole table, is DDL, cannot easily rollback, resets counter.', 10, 240, 1.50, 1),
(95, 7, NULL, 'final', 5, 'Practical Task 5: Write an SQL query that retrieves the candidate''s full name, email, and position title by joining the candidates table with the positions table on position_id.', 'practical', 'SELECT c.full_name, c.email, p.title FROM candidates c JOIN positions p ON c.position_id = p.id;', 10, 240, 1.50, 1),
(101, 8, NULL, 'final', 5, 'Practical Task 1: Write 2 different email subject lines for a new product announcement: one focusing on curiosity/benefit and the other focusing on urgency/time.', 'practical', 'Curiosity: "How top teams cut hiring time by 50% 🚀"; Urgency: "Only 24 hours left: Early access pricing ends tonight ⏳"', 10, 240, 1.50, 1),
(102, 8, NULL, 'final', 5, 'Practical Task 2: If an email was sent to 5,000 subscribers, 1,000 opened the email, and 150 clicked a link inside, calculate the Open Rate percentage and Click-Through Rate (CTR) percentage.', 'practical', 'Open Rate = (1,000 / 5,000) * 100 = 20.0%; CTR = (150 / 5,000) * 100 = 3.0% (Click-to-Open Rate = 15.0%).', 10, 240, 1.50, 1),
(103, 8, NULL, 'final', 5, 'Practical Task 3: You notice that email deliverability suddenly dropped and open rates decreased. List 3 quick checks you will perform (sender reputation, spam words, subscriber list quality).', 'practical', '1. Check DNS records (SPF/DKIM/DMARC), 2. Check blacklist monitors/sender domain score, 3. Inspect email copy for spam triggers, 4. Prune unengaged subscribers.', 10, 240, 1.50, 1),
(104, 8, NULL, 'final', 5, 'Practical Task 4: Outline a 3-email welcome drip sequence for new subscribers (Email 1: Welcome & gift/intro, Email 2: Value & best resources, Email 3: Community invite / call to action).', 'practical', 'Email 1 (Day 0): Welcome and instant resource delivery. Email 2 (Day 2): Case study and helpful tips. Email 3 (Day 4): Book a personal software walkthrough.', 10, 240, 1.50, 1),
(105, 8, NULL, 'final', 5, 'Practical Task 5: Explain the difference between a Hard Bounce and a Soft Bounce in email marketing, and what action should be taken immediately for hard bounces.', 'practical', 'Hard bounce is a permanent error (invalid address/domain) and must be immediately removed; Soft bounce is temporary (mailbox full/server down) and can be retried.', 10, 240, 1.50, 1)
